"""Ordinary-user real-template preparation; no UB/Guest/service/module actions."""
import argparse,base64,hashlib,json,os,platform,re,selectors,shutil,stat,struct,subprocess,sys,time,zlib
from pathlib import Path

CORE_COMMIT='4185da5e2037f3032ee9ef6bab06f7085403c64b'
PACKAGE_SHA='665b5a84ff4fd0da4b6d17b5b71118eeadb968dc9a18a1b4684a971a9400ec9b'
PACKAGE=''
ROOT=Path('/home/jwk/agent')
SELECTOR_SHA='de7d33573d8ae46d37c08e811973deab20d16cf855adf256f9b7b6f25bbb7cc0'
MIB=1024**2

def need(value,reason):
    if not value:raise RuntimeError(reason)

def save(path,value):
    with path.open('x',encoding='utf-8') as f:json.dump(value,f,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())

def digest(path,size=None):
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
    with os.fdopen(fd,'rb') as f:
        before=os.fstat(f.fileno())
        need(stat.S_ISREG(before.st_mode) and (size is None or before.st_size==size),'File identity differs')
        result=hashlib.sha256()
        for data in iter(lambda:f.read(MIB),b''):result.update(data)
        after=os.fstat(f.fileno())
        need((before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns,before.st_ctime_ns)==
             (after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns,after.st_ctime_ns),'File changed during hash')
        return result.hexdigest()

def tool(name):
    for directory in ('/usr/sbin','/sbin','/usr/bin','/bin'):
        path=Path(directory)/name
        if path.is_file():
            info=path.resolve(strict=True).stat()
            need(info.st_uid==0 and not info.st_mode&0o022,'System tool ownership differs')
            return str(path)
    raise RuntimeError('Missing preparation tool: '+name)

def command(args,log):
    with log.open('xb') as output:
        result=subprocess.run(args,stdin=subprocess.DEVNULL,stdout=output,stderr=subprocess.STDOUT,timeout=600)
    need(result.returncode==0,'Preparation command failed; inspect '+str(log))

def streamed_image_file_hash(debugfs,image,name,log):
    """Read one file from the image without a mounted filesystem or temp copy."""
    with log.open('xb') as errors:
        process=subprocess.Popen([debugfs,'-R','cat /'+name,str(image)],stdin=subprocess.DEVNULL,
                                 stdout=subprocess.PIPE,stderr=errors)
        try:
            poll=selectors.DefaultSelector();poll.register(process.stdout,selectors.EVENT_READ)
            end=time.monotonic()+600;sha=hashlib.sha256();count=0
            while True:
                need(time.monotonic()<end,'Image file verification timed out')
                if not poll.select(timeout=1):continue
                chunk=os.read(process.stdout.fileno(),MIB)
                if not chunk:break
                sha.update(chunk);count+=len(chunk)
            need(process.wait(timeout=10)==0,'debugfs verification failed')
            return count,sha.hexdigest()
        finally:
            if process.poll() is None:
                process.terminate()
                try:process.wait(timeout=10)
                except subprocess.TimeoutExpired:process.kill();process.wait()
            process.stdout.close()
            if 'poll' in locals():poll.close()

def image_size(total):
    return ((total+64*MIB+4*MIB-1)//(4*MIB))*(4*MIB)

def binary_inventory():
    rows=[]
    for deployment in ('agentenv-ae9c626-baseline','agentenv-direct-ub-deletefix-v1','agentenv-dsec-hostfile-v1'):
        for name in ('server','uvm-ublk-daemon','firecracker'):
            path=ROOT/'deployments'/deployment/'bin'/name
            if not path.exists():continue
            resolved=path.resolve(strict=True)
            need(resolved.is_relative_to(ROOT),'Retained binary redirects outside workspace')
            info=resolved.stat()
            need(stat.S_ISREG(info.st_mode) and info.st_uid in (0,1204) and 0<info.st_size<=512*MIB,'Unexpected retained binary')
            rows.append({'path':str(path),'resolvedPath':str(resolved),'bytes':info.st_size,'sha256':digest(resolved,info.st_size),
                         'executed':False,'sourceRevisionNotInferredFromFilename':True})
    return rows

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--run',action='store_true')
    args=parser.parse_args()
    node={'server1':'a','agent1':'b'}[platform.node()]
    need(os.getuid()==os.geteuid()==1204 and os.getgid()==1205,'Run as ordinary jwk UID1204/GID1205, not root')
    need(Path.cwd()==ROOT and ROOT.resolve(strict=True)==ROOT,'Expected existing workspace')
    selector=ROOT/'AB_direct_full_host_v1.py'
    need(digest(selector,81083)==SELECTOR_SHA,'Retained template selector differs')
    scope={'__name__':'verified_selection_only','__file__':str(selector)}
    exec(compile(selector.read_bytes(),str(selector),'exec'),scope)
    selection=scope['selection'](node)  # Metadata only; never invoke owner/import/retire.
    layers=selection['layers'];need(len(layers)==8,'Expected the retained single-template eight lowers')
    size=image_size(selection['logicalBytes'])
    need(size<=2*1024**3,'Prepared image exceeds the proposed 2GiB logical ceiling')
    work=ROOT/'r'/('hpd4-'+node+'-v1')
    report={'status':'HOST_DAX_ROOTFS_PREPARATION_PLAN','node':node,'coreCommit':CORE_COMMIT,
        'workDirectory':str(work),'templateIndex':0,'templateId':'01a15c9e-54d0-7b92-a50b-0b6ec2e9136b',
        'files':layers,'logicalLowerBytes':selection['logicalBytes'],'containerBytes':size,
        'proposedPostMapCoverageGuardBytes':4*1024**3,'physicalHardQuota':False,
        'SDK_called':False,'Guest_created':False,'servicesChanged':False,'moduleChanged':False,
        'existingSyntheticPublicationChanged':False,'twoNodeAccepted':False,'netSavingsBytes':None}
    previous=ROOT/'r'/('hpmem-'+node+'-v1')/'prepared.json'
    prepared=json.loads(previous.read_text())
    adapter=prepared['adapter']
    need(adapter['sha256']=='34ed1c5666b5628cc37b4c75f95a44766b0cd119eb02f0df8c9ce15a54bcdfa0'
         and digest(Path(adapter['path']))==adapter['sha256'],'Retained native-pmem adapter differs')
    sdk=Path('/usr/lib64/libubsm_sdk.so').resolve(strict=True)
    need(digest(sdk)=='88686bc4e869c6442eb7d88128a2d3efd82468696c489734fc80b4692ac60223','SDK bytes differ')
    report.update(adapter=adapter,kernelRelease=platform.release(),bootId=Path('/proc/sys/kernel/random/boot_id').read_text().strip(),
        moduleSrcversion=Path('/sys/module/obmm/srcversion').read_text().strip(),
        pmemReadonlyEnabled=Path('/sys/module/obmm/parameters/pmem_ro_enable').read_text().strip())
    if not args.run:print(json.dumps(report,indent=2));return
    need(not work.exists() and not work.is_symlink(),'Preparation exists; preserve it, do not rerun')
    for layer in layers:
        need(digest(Path(layer['file']),layer['size'])==layer['digest'][7:],'Retained lower content differs')
    mke2fs=tool('mke2fs') if node=='a' else None;debugfs=tool('debugfs') if node=='a' else None
    need(shutil.disk_usage(ROOT/'r').free>=3*size,'Insufficient preparation disk headroom')
    work.mkdir(mode=0o700);save(work/'intent.json',report)
    archive=zlib.decompress(base64.b64decode(PACKAGE,validate=True))
    need(hashlib.sha256(archive).hexdigest()==PACKAGE_SHA,'Embedded core package differs')
    package=json.loads(archive);source=work/'source';source.mkdir(mode=0o700)
    for category,directory in [('modules','aenv_ub_provider'),('tests','tests')]:
        target=source/directory;target.mkdir(mode=0o700)
        for name,code in package[category].items():
            need(Path(name).name==name and name.endswith('.py'),'Unexpected package member')
            with (target/name).open('x',encoding='utf-8') as f:f.write(code)
    bootstrap="import sys,unittest;sys.path.insert(0,sys.argv[1]);s=unittest.defaultTestLoader.discover(sys.argv[1]+'/tests');r=unittest.TextTestRunner().run(s);raise SystemExit(not r.wasSuccessful())"
    print('PHASE=native-python-contract-tests',flush=True)
    command(['/usr/bin/python3','-I','-B','-c',bootstrap,str(source)],work/'provider-tests.log')
    report['pythonContractTestsExitCode']=0
    files=[{'name':layer['digest'][7:]+'.commit','digest':layer['digest'],'bytes':layer['size']} for layer in layers]
    if node=='a':
        image=work/'rootfs-lowers.ext4'
        with image.open('xb') as f:f.truncate(size);f.flush();os.fsync(f.fileno())
        print('PHASE=build-dedicated-rootfs-lower-container',flush=True)
        command([mke2fs,'-q','-F','-t','ext4','-b','4096','-m','0','-O','^has_journal,^inline_data',
                 '-E','lazy_itable_init=0,lazy_journal_init=0',str(image)],work/'mke2fs.log')
        for i,(layer,item) in enumerate(zip(layers,files)):
            need(re.fullmatch(r'[A-Za-z0-9_./:\-]+',layer['file']) is not None,'Unsupported debugfs source path')
            print('PHASE=pack-and-verify-lower-'+str(i+1)+'-of-8',flush=True)
            command([debugfs,'-w','-R','write '+layer['file']+' /'+item['name'],str(image)],work/('write-'+str(i)+'.log'))
            count,sha=streamed_image_file_hash(debugfs,image,item['name'],work/('verify-'+str(i)+'.log'))
            need(count==item['bytes'] and 'sha256:'+sha==item['digest'],'Packed lower content differs')
        with image.open('r+b') as f:
            os.fsync(f.fileno());f.seek(1024);sb=f.read(1024)
        need(len(sb)==1024 and struct.unpack_from('<H',sb,56)[0]==0xef53
             and struct.unpack_from('<I',sb,24)[0]==2 and struct.unpack_from('<I',sb,4)[0]==size//4096
             and struct.unpack_from('<H',sb,58)[0]&1 and not struct.unpack_from('<I',sb,92)[0]&4
             and not struct.unpack_from('<I',sb,96)[0]&0x8000,'Container superblock differs')
        report['image']={'path':str(image),'bytes':size,'sha256':digest(image,size),'files':files}
    else:report['image']=None
    for layer in layers:
        info=Path(layer['file']).stat()
        need([info.st_dev,info.st_ino,info.st_size,info.st_mtime_ns,info.st_ctime_ns]==layer['fileIdentity'],
             'Original lower identity changed during preparation')
    report['retainedBinaryInventory']=binary_inventory()
    report.update(status='HOST_DAX_REAL_TEMPLATE_PREPARED_NO_SDK',packageSha256=PACKAGE_SHA,
        originalLowerBytesUnchanged=True,originalLowerMetadataUnchanged=True,
        fsDaxHardwareTested=False,childCredentialHandoffHardwareTested=False)
    save(work/'prepared.json',report)
    print('BEGIN_HOST_DAX_ROOTFS_PREPARATION');print(json.dumps(report,indent=2));print('END_HOST_DAX_ROOTFS_PREPARATION')

if __name__=='__main__':
    try:main()
    except Exception as error:
        print(json.dumps({'status':'HOST_DAX_ROOTFS_PREPARATION_STOPPED_PRESERVE_FILES','reason':str(error),
                          'SDK_called':False,'Guest_created':False,'servicesChanged':False,'moduleChanged':False}),flush=True)
        raise SystemExit(1)
